//! upload-pack: request parsing, object closure walk, pack writing, and the
//! streamed response body (milestone 2).
//!
//! Streaming design: every callback deterministically regenerates the full
//! response body and slices out its chunk. Objects are immutable and never
//! deleted, and the wants/haves are pinned in the callback token, so the
//! regenerated bytes are identical on every call - no cross-callback state,
//! and a push landing mid-clone cannot corrupt the stream. The cost is a full
//! body rebuild per chunk; fine within the 5B-instruction query budget for
//! packs up to tens of MiB, and optimizable later with a prefix-hash cache.

use crate::object;
use crate::smart_http::{parse_pkt_lines, pkt_line, FLUSH_PKT};
use crate::store::{self, ObjectType, Oid};
use ic_dev_kit_rs::http::{StreamingCallbackHttpResponse, StreamingCallbackToken};
use serde::{Deserialize, Serialize};
use sha1::{Digest, Sha1};
use std::collections::{BTreeSet, VecDeque};

/// HTTP-body bytes per streaming response; margin under the 3 MiB query cap.
pub const STREAM_CHUNK: usize = 1_500_000;

/// Sideband band-1 data bytes per pkt (side-band-64k: 65520-byte pkts).
const SIDEBAND_DATA: usize = 65515;

pub struct UploadPackRequest {
    pub wants: Vec<Oid>,
    pub haves: Vec<Oid>,
    pub done: bool,
    pub sideband: bool,
}

pub fn parse_request(body: &[u8]) -> Result<UploadPackRequest, String> {
    let mut req = UploadPackRequest {
        wants: Vec::new(),
        haves: Vec::new(),
        done: false,
        sideband: false,
    };
    let mut pos = 0;
    while pos < body.len() {
        let (lines, consumed) = parse_pkt_lines(&body[pos..])?;
        if consumed == 0 {
            break;
        }
        pos += consumed;
        for line in &lines {
            let line = std::str::from_utf8(line)
                .map_err(|_| "non-utf8 pkt line")?
                .trim_end();
            if line.is_empty() {
                continue; // flush marker
            }
            if let Some(rest) = line.strip_prefix("want ") {
                let hex = rest.get(..40).ok_or("short want line")?;
                req.wants.push(store::parse_oid(hex)?);
                // Capabilities the client selected ride on the first want line.
                if rest[40..].contains("side-band-64k") {
                    req.sideband = true;
                }
            } else if let Some(rest) = line.strip_prefix("have ") {
                req.haves
                    .push(store::parse_oid(rest.get(..40).ok_or("short have line")?)?);
            } else if line == "done" {
                req.done = true;
            } else {
                // shallow/deepen/filter would land here; none are advertised.
                return Err(format!("unsupported request line: {line}"));
            }
        }
    }
    if req.wants.is_empty() {
        return Err("no wants in request".into());
    }
    Ok(req)
}

// --- closure walk -----------------------------------------------------------

/// Child object ids referenced by a non-blob object: the objects that
/// must be in the store for it to be whole there, and that go with it in
/// a pack.
///
/// A submodule's entry is none. It names a commit of another repo, and
/// git neither sends that commit in a push nor expects it in a fetch.
/// Until 2026-11 it was taken for a child, so a push of a repo with a
/// submodule was refused for missing objects -- unless the store, which
/// is one for every repo, held that commit for another repo: then the
/// push went through and every clone carried the submodule's whole
/// history with it.
fn children(object_type: ObjectType, content: &[u8]) -> Result<Vec<Oid>, String> {
    Ok(match object_type {
        ObjectType::Blob => Vec::new(),
        ObjectType::Commit => {
            let refs = object::commit_refs(content)?;
            let mut out = vec![refs.tree];
            out.extend(refs.parents);
            out
        }
        ObjectType::Tag => vec![object::tag_target(content)?],
        ObjectType::Tree => object::tree_entries(content)?
            .into_iter()
            .filter(|e| !object::is_gitlink_mode(&e.mode))
            .map(|e| e.oid)
            .collect(),
    })
}

/// BFS over the object graph from `roots`, skipping anything in `stop`.
/// Blobs are never inflated - their type comes from the value prefix and they
/// have no children. `strict` errors on missing objects (wants must be fully
/// present); the lenient form skips them (haves may reference history we
/// never had).
fn reachable(
    roots: &[Oid],
    stop: &BTreeSet<Oid>,
    strict: bool,
) -> Result<Vec<(Oid, ObjectType)>, String> {
    let mut visited: BTreeSet<Oid> = BTreeSet::new();
    let mut out = Vec::new();
    let mut queue: VecDeque<Oid> = roots.iter().copied().collect();
    while let Some(oid) = queue.pop_front() {
        if visited.contains(&oid) || stop.contains(&oid) {
            continue;
        }
        let Some(stored) = store::get_object_stored(&oid) else {
            if strict {
                return Err(format!("missing object {}", store::oid_hex(&oid)));
            }
            continue;
        };
        visited.insert(oid);
        out.push((oid, stored.object_type));
        if stored.object_type != ObjectType::Blob {
            for child in children(stored.object_type, &stored.content())? {
                if !visited.contains(&child) {
                    queue.push_back(child);
                }
            }
        }
    }
    Ok(out)
}

/// Objects to pack: everything reachable from `wants` minus everything
/// reachable from the haves we actually possess (the client has those; the
/// lenient walk skips haves we never had).
pub fn closure(wants: &[Oid], haves: &[Oid]) -> Result<Vec<(Oid, ObjectType)>, String> {
    let have_set: BTreeSet<Oid> = reachable(haves, &BTreeSet::new(), false)?
        .into_iter()
        .map(|(oid, _)| oid)
        .collect();
    reachable(wants, &have_set, true)
}

/// The commits and tags within reach of `tips`, and the tips themselves:
/// the history a push's connectivity check may stop at (`connected`). No
/// tree and no blob is read. Whatever a ref reaches was whole when the
/// ref was set, so reaching one of these is reaching objects that are all
/// there. A tip the store does not hold is skipped.
pub fn history(tips: &[Oid]) -> BTreeSet<Oid> {
    let mut seen: BTreeSet<Oid> = BTreeSet::new();
    let mut queue: Vec<Oid> = tips.to_vec();
    while let Some(oid) = queue.pop() {
        if !seen.insert(oid) {
            continue;
        }
        // The type is read off the stored value: a tree or a blob a ref
        // or a tag names is not inflated to learn it is neither.
        let Some(stored) = store::get_object_stored(&oid) else {
            seen.remove(&oid);
            continue;
        };
        match stored.object_type {
            ObjectType::Commit => {
                if let Ok(refs) = object::commit_refs(&stored.content()) {
                    queue.extend(refs.parents);
                }
            }
            ObjectType::Tag => queue.extend(object::tag_target(&stored.content()).ok()),
            ObjectType::Tree | ObjectType::Blob => {}
        }
    }
    seen
}

/// Is everything `new` reaches in the store? The walk stops at `known`,
/// objects already shown to be whole, and on success adds what it
/// visited to them: a push's commands share one `known`, so each walks
/// only what the ones before it did not.
pub fn connected(new: &Oid, known: &mut BTreeSet<Oid>) -> Result<(), String> {
    let visited = reachable(&[*new], known, true)?;
    known.extend(visited.into_iter().map(|(oid, _)| oid));
    Ok(())
}

// --- pack format ------------------------------------------------------------
// Encoder (upload-pack) and decoder (receive-pack) of the same wire layout,
// kept adjacent so they cannot drift apart.

const OFS_DELTA: u8 = 6;
const REF_DELTA: u8 = 7;

/// Pack entry header: type code in bits 6-4 of the first byte, size in
/// little-endian 4+7+7+... bit groups with MSB continuation.
fn push_entry_header(pack: &mut Vec<u8>, type_code: u8, size: u64) {
    let mut byte = (type_code << 4) | (size & 0x0F) as u8;
    let mut size = size >> 4;
    while size > 0 {
        pack.push(byte | 0x80);
        byte = (size & 0x7F) as u8;
        size >>= 7;
    }
    pack.push(byte);
}

/// Decode an entry header at `pos`: (type code, inflated size, next pos).
/// For delta entries the size is the inflated size of the delta data.
fn parse_entry_header(data: &[u8], mut pos: usize) -> Result<(u8, u64, usize), String> {
    let mut byte = *data.get(pos).ok_or("truncated pack entry")?;
    pos += 1;
    let type_code = (byte >> 4) & 0x07;
    let mut size = (byte & 0x0F) as u64;
    let mut shift = 4;
    while byte & 0x80 != 0 {
        byte = *data.get(pos).ok_or("truncated size varint")?;
        pos += 1;
        size |= ((byte & 0x7F) as u64) << shift;
        shift += 7;
    }
    Ok((type_code, size, pos))
}

/// OFS_DELTA base offset: big-endian 7-bit groups where each continuation
/// adds an implicit +1 (git's "offset encoding").
fn parse_ofs_offset(data: &[u8], mut pos: usize) -> Result<(u64, usize), String> {
    let mut byte = *data.get(pos).ok_or("truncated ofs offset")?;
    pos += 1;
    let mut offset = (byte & 0x7F) as u64;
    while byte & 0x80 != 0 {
        byte = *data.get(pos).ok_or("truncated ofs offset")?;
        pos += 1;
        offset = ((offset + 1) << 7) | (byte & 0x7F) as u64;
    }
    Ok((offset, pos))
}

/// Little-endian 7-bit size varint used inside delta data.
fn parse_delta_size(delta: &[u8], mut pos: usize) -> Result<(u64, usize), String> {
    let mut size = 0u64;
    let mut shift = 0;
    loop {
        let byte = *delta.get(pos).ok_or("truncated delta size")?;
        pos += 1;
        size |= ((byte & 0x7F) as u64) << shift;
        shift += 7;
        if byte & 0x80 == 0 {
            return Ok((size, pos));
        }
    }
}

/// The largest object a pack may carry or a delta may make, inflated. A
/// pack entry declares its size and a delta its result's, in a few bytes
/// that cost nothing to send; nothing is inflated or built past either.
pub const MAX_OBJECT: u64 = 64 << 20;

/// The most reading a pack may inflate: its objects, all together, and
/// every base a delta is applied to, each time it is (a base is inflated
/// again for each delta on it, so a pack of tiny deltas on one large base
/// is this much work without making this many bytes). A push is one
/// request body (2 MB at the gateway), which a pack of ordinary files and
/// deltas does not turn into this much. Chosen, not measured: it bounds
/// the heap `prepare` holds and the work one push can ask for.
pub const MAX_PACK_INFLATED: u64 = 256 << 20;

/// Apply a git delta (copy/insert instruction stream) to `base`.
pub fn apply_delta(base: &[u8], delta: &[u8]) -> Result<Vec<u8>, String> {
    let (src_size, pos) = parse_delta_size(delta, 0)?;
    if src_size != base.len() as u64 {
        return Err("delta source size mismatch".into());
    }
    let (dst_size, mut pos) = parse_delta_size(delta, pos)?;
    // The size is the delta's own word: asked before anything is reserved
    // for it, and held to as the result is built.
    if dst_size > MAX_OBJECT {
        return Err(format!("delta makes an object of {dst_size} bytes; the most is {MAX_OBJECT}"));
    }
    let dst_size = dst_size as usize;
    let mut out = Vec::with_capacity(dst_size);
    while pos < delta.len() {
        let op = delta[pos];
        pos += 1;
        if op & 0x80 != 0 {
            // Copy from base: bits 0-3 select offset bytes, 4-6 size bytes.
            let mut offset = 0u64;
            let mut size = 0u64;
            for i in 0..4 {
                if op & (1 << i) != 0 {
                    offset |= (*delta.get(pos).ok_or("truncated copy offset")? as u64) << (8 * i);
                    pos += 1;
                }
            }
            for i in 0..3 {
                if op & (1 << (4 + i)) != 0 {
                    size |= (*delta.get(pos).ok_or("truncated copy size")? as u64) << (8 * i);
                    pos += 1;
                }
            }
            if size == 0 {
                size = 0x10000;
            }
            let start = offset as usize;
            let end = start.checked_add(size as usize).ok_or("copy overflow")?;
            if out.len() + size as usize > dst_size {
                return Err("delta target size mismatch".into());
            }
            out.extend_from_slice(base.get(start..end).ok_or("delta copy out of range")?);
        } else if op != 0 {
            // Insert literal bytes.
            let n = op as usize;
            if out.len() + n > dst_size {
                return Err("delta target size mismatch".into());
            }
            out.extend_from_slice(delta.get(pos..pos + n).ok_or("delta insert out of range")?);
            pos += n;
        } else {
            return Err("delta opcode 0".into());
        }
    }
    if out.len() != dst_size {
        return Err("delta target size mismatch".into());
    }
    Ok(out)
}

/// Inflate one zlib stream starting at `pos`, which the entry says is
/// `size` bytes inflated; returns (content, bytes consumed). Nothing is
/// inflated past the size: a stream that has more is refused there.
fn inflate_from(data: &[u8], pos: usize, size: u64) -> Result<(Vec<u8>, usize), String> {
    if size > MAX_OBJECT {
        return Err(format!("pack entry of {size} bytes; the most is {MAX_OBJECT}"));
    }
    let mut decoder = flate2::read::ZlibDecoder::new(data.get(pos..).ok_or("truncated pack entry")?);
    let mut out = Vec::new();
    std::io::Read::read_to_end(&mut std::io::Read::take(&mut decoder, size + 1), &mut out).map_err(|e| format!("pack zlib: {e}"))?;
    if out.len() as u64 != size {
        return Err("entry size mismatch".into());
    }
    Ok((out, decoder.total_in() as usize))
}

/// A received pack with its deltas resolved and nothing stored yet: every
/// object as the store would keep it, and what that comes to. Made before
/// the push is charged, so the charge is for what the pack stores and not
/// for its bytes on the wire, which a delta makes as small as it likes: a
/// few bytes of delta copy a megabyte of base into a new object.
pub struct Prepared {
    /// In pack order. The value is `None` for an object the store or an
    /// earlier entry already has.
    objects: Vec<(Oid, Option<Vec<u8>>)>,
    stored_bytes: u64,
}

impl Prepared {
    /// The bytes storing this pack adds: the stored values of its objects
    /// that the store does not have.
    pub fn stored_bytes(&self) -> u64 {
        self.stored_bytes
    }

    /// Store every object. Returns the oids in pack order.
    pub fn store(self) -> Vec<Oid> {
        self.objects
            .into_iter()
            .map(|(oid, value)| {
                // Another push may have stored it since `prepare`, and the
                // first value is the one kept: the same object, but its
                // zlib stream may differ (a client's, or deflated here),
                // and a fetch being streamed is rebuilt from the stored
                // streams chunk by chunk, so one must not change under it.
                if let Some(value) = value {
                    if !store::has_object(&oid) {
                        store::put_stored(oid, value);
                    }
                }
                oid
            })
            .collect()
    }
}

/// Parse a received pack, verify the trailer, and resolve deltas (bases in
/// the pack are read back from what was prepared, a thin pack's from the
/// store). Stores nothing.
pub fn prepare(data: &[u8]) -> Result<Prepared, String> {
    if data.len() < 32 || &data[..4] != b"PACK" {
        return Err("bad pack header".into());
    }
    let version = u32::from_be_bytes(data[4..8].try_into().unwrap());
    if version != 2 && version != 3 {
        return Err(format!("unsupported pack version {version}"));
    }
    let count = u32::from_be_bytes(data[8..12].try_into().unwrap());
    let content_end = data.len() - 20;
    let digest: [u8; 20] = Sha1::digest(&data[..content_end]).into();
    if digest.as_slice() != &data[content_end..] {
        return Err("pack checksum mismatch".into());
    }
    // An entry is at least a header byte and an empty zlib stream.
    if count as usize > data.len() / 9 {
        return Err("pack object count exceeds its length".into());
    }

    let mut pos = 12;
    // Entry start offset -> index, for OFS_DELTA base resolution, and oid ->
    // index of the entry whose value is held here, for bases the store does
    // not have yet. Bases are inflated again from the prepared value rather
    // than kept inflated: the heap holds what will be stored and no more.
    let mut by_offset: std::collections::BTreeMap<usize, usize> = std::collections::BTreeMap::new();
    let mut held: std::collections::BTreeMap<Oid, usize> = std::collections::BTreeMap::new();
    let mut objects: Vec<(Oid, Option<Vec<u8>>)> = Vec::with_capacity(count as usize);
    let (mut inflated, mut stored_bytes) = (0u64, 0u64);

    for _ in 0..count {
        let entry_start = pos;
        let (type_code, size, p) = parse_entry_header(data, pos)?;
        pos = p;
        let (object_type, content, zlib) = match type_code {
            1..=4 => {
                let (content, consumed) = inflate_from(data, pos, size)?;
                // The wire zlib stream is exactly what the store persists;
                // reuse it instead of re-deflating the content.
                let zlib = data.get(pos..pos + consumed).ok_or("truncated pack entry")?;
                pos += consumed;
                (ObjectType::from_pack_code(type_code).unwrap(), content, Some(zlib))
            }
            OFS_DELTA | REF_DELTA => {
                let base_oid = if type_code == OFS_DELTA {
                    let (offset, p) = parse_ofs_offset(data, pos)?;
                    pos = p;
                    let base_start = entry_start
                        .checked_sub(offset as usize)
                        .ok_or("ofs delta offset out of range")?;
                    objects[*by_offset.get(&base_start).ok_or("ofs delta base not found")?].0
                } else {
                    let oid =
                        Oid::try_from(data.get(pos..pos + 20).ok_or("truncated ref delta base")?)
                            .unwrap();
                    pos += 20;
                    oid
                };
                let (delta, consumed) = inflate_from(data, pos, size)?;
                pos += consumed;
                let held_base = held.get(&base_oid).and_then(|i| objects[*i].1.as_deref()).map(store::parse_stored);
                let (base_type, base) = held_base
                    .or_else(|| store::get_object_parsed(&base_oid))
                    .ok_or_else(|| format!("delta base {} missing", store::oid_hex(&base_oid)))?;
                inflated += base.len() as u64;
                (base_type, apply_delta(&base, &delta)?, None)
            }
            t => return Err(format!("unsupported pack entry type {t}")),
        };
        inflated += content.len() as u64;
        if inflated > MAX_PACK_INFLATED {
            return Err(format!("the pack's objects and delta bases come to more than {MAX_PACK_INFLATED} bytes inflated; push it in parts"));
        }
        let oid = store::oid_of(object_type, &content);
        let value = if held.contains_key(&oid) || store::has_object(&oid) {
            None
        } else {
            let value = match zlib {
                Some(zlib) => store::stored_value_zlib(object_type, content.len(), zlib),
                None => store::stored_value(object_type, &content),
            };
            stored_bytes += value.len() as u64;
            held.insert(oid, objects.len());
            Some(value)
        };
        by_offset.insert(entry_start, objects.len());
        objects.push((oid, value));
    }
    if pos != content_end {
        return Err("pack length mismatch".into());
    }
    Ok(Prepared { objects, stored_bytes })
}

/// `prepare` and store, for a pack nobody is charged for.
pub fn ingest_pack(data: &[u8]) -> Result<Vec<Oid>, String> {
    Ok(prepare(data)?.store())
}

/// A version-2 packfile with no deltas: stored zlib streams are emitted
/// verbatim after their entry headers.
pub fn build_pack(objects: &[(Oid, ObjectType)]) -> Vec<u8> {
    let mut pack = Vec::new();
    pack.extend_from_slice(b"PACK");
    pack.extend_from_slice(&2u32.to_be_bytes());
    pack.extend_from_slice(&(objects.len() as u32).to_be_bytes());
    for (oid, _) in objects {
        let stored = store::get_object_stored(oid).expect("closure object exists");
        push_entry_header(&mut pack, stored.object_type as u8, stored.size as u64);
        pack.extend_from_slice(stored.zlib());
    }
    let digest: [u8; 20] = Sha1::digest(&pack).into();
    pack.extend_from_slice(&digest);
    pack
}

// --- response body & streaming ----------------------------------------------

pub enum UploadPackReply {
    /// Negotiation continues; the client has not sent `done` yet. With no
    /// multi_ack advertised, policy is to single-NAK every round.
    Negotiating(Vec<u8>),
    /// The full response body: NAK then the (possibly sideband-framed) pack.
    Pack(Vec<u8>),
}

pub fn respond(req: &UploadPackRequest) -> Result<UploadPackReply, String> {
    if !req.done {
        return Ok(UploadPackReply::Negotiating(pkt_line(b"NAK\n")));
    }
    Ok(UploadPackReply::Pack(response_body(req)?))
}

fn response_body(req: &UploadPackRequest) -> Result<Vec<u8>, String> {
    let objects = closure(&req.wants, &req.haves)?;
    let pack = build_pack(&objects);
    let mut body = pkt_line(b"NAK\n");
    if req.sideband {
        // Per frame: 4 hex length bytes + 1 band byte, written in place.
        body.reserve(pack.len() + (pack.len() / SIDEBAND_DATA + 1) * 5 + FLUSH_PKT.len());
        for chunk in pack.chunks(SIDEBAND_DATA) {
            body.extend_from_slice(format!("{:04x}", chunk.len() + 5).as_bytes());
            body.push(1); // band 1: pack data
            body.extend_from_slice(chunk);
        }
        body.extend_from_slice(FLUSH_PKT);
    } else {
        body.extend_from_slice(&pack);
    }
    Ok(body)
}

/// The immutable request state a callback needs to regenerate the body,
/// JSON-packed into the token's `key`; the chunk number rides in the token's
/// own `index` field.
#[derive(Serialize, Deserialize)]
struct TokenState {
    w: Vec<String>,
    h: Vec<String>,
    sb: bool,
}

pub fn stream_token(req: &UploadPackRequest, next_chunk: u64) -> StreamingCallbackToken {
    let state = TokenState {
        w: req.wants.iter().map(store::oid_hex).collect(),
        h: req.haves.iter().map(store::oid_hex).collect(),
        sb: req.sideband,
    };
    StreamingCallbackToken {
        key: serde_json::to_string(&state).expect("token serializes"),
        content_encoding: "identity".to_string(),
        index: candid::Nat::from(next_chunk),
        sha256: None,
    }
}

pub fn next_chunk(token: &StreamingCallbackToken) -> Result<StreamingCallbackHttpResponse, String> {
    let index = u64::try_from(&token.index.0).map_err(|_| "bad token index")? as usize;
    let state: TokenState =
        serde_json::from_str(&token.key).map_err(|e| format!("bad token: {e}"))?;
    let req = UploadPackRequest {
        wants: state
            .w
            .iter()
            .map(|h| store::parse_oid(h))
            .collect::<Result<_, _>>()?,
        haves: state
            .h
            .iter()
            .map(|h| store::parse_oid(h))
            .collect::<Result<_, _>>()?,
        done: true,
        sideband: state.sb,
    };
    let body = response_body(&req)?;
    let start = index * STREAM_CHUNK;
    if start >= body.len() {
        return Err("token past end of body".into());
    }
    let end = (start + STREAM_CHUNK).min(body.len());
    Ok(StreamingCallbackHttpResponse {
        body: body[start..end].to_vec(),
        token: (end < body.len()).then(|| StreamingCallbackToken {
            index: candid::Nat::from(index as u64 + 1),
            ..token.clone()
        }),
    })
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn entry_header_varint() {
        let mut small = Vec::new();
        push_entry_header(&mut small, ObjectType::Blob as u8, 5);
        assert_eq!(small, vec![0b0011_0101]); // type 3, size 5, no continuation

        let mut large = Vec::new();
        // 2684: low 4 bits (0b1100) + type 1 + MSB; then 7 bits 0b010_0111 +
        // MSB (the remaining group 0b1010_0111 exceeds 7 bits); then final 0b1.
        push_entry_header(&mut large, ObjectType::Commit as u8, 0b1010_0111_1100);
        assert_eq!(large, vec![0b1001_1100, 0b1010_0111, 0b0000_0001]);
    }

    #[test]
    fn delta_copy_and_insert() {
        let base = b"hello world";
        // src size 11, dst size 16; copy(offset 0, size 5) + insert " there" +
        // copy(offset 5, size 6) -> "hello there world"... sizes: 5+6+6 = 17.
        let mut delta = vec![11, 17];
        delta.push(0b1001_0001); // copy: offset byte 0 present, size byte 0 present
        delta.extend_from_slice(&[0, 5]);
        delta.push(6); // insert 6 literal bytes
        delta.extend_from_slice(b" there");
        delta.push(0b1001_0001);
        delta.extend_from_slice(&[5, 6]);
        assert_eq!(apply_delta(base, &delta).unwrap(), b"hello there world");

        assert!(apply_delta(b"wrong len", &delta).is_err());
    }

    #[test]
    fn ingest_round_trips_built_pack() {
        // Build objects, pack them with our writer, wipe nothing (the store
        // is content-addressed so re-ingest is idempotent), ingest, compare.
        let blob = store::put_object(ObjectType::Blob, b"round trip");
        let mut tree = Vec::new();
        tree.extend_from_slice(b"100644 f\0");
        tree.extend_from_slice(blob.as_slice());
        let tree = store::put_object(ObjectType::Tree, &tree);
        let pack = build_pack(&[(blob, ObjectType::Blob), (tree, ObjectType::Tree)]);

        let oids = ingest_pack(&pack).unwrap();
        assert_eq!(oids, vec![blob, tree]);

        // Corrupt the trailer: must be rejected.
        let mut bad = pack.clone();
        let n = bad.len();
        bad[n - 1] ^= 0xFF;
        assert!(ingest_pack(&bad).unwrap_err().contains("checksum"));
    }

    #[test]
    fn ingest_resolves_ref_delta_against_store() {
        let base_content = b"the quick brown fox jumps over the lazy dog";
        let base = store::put_object(ObjectType::Blob, base_content);

        // Delta: copy the whole base, then append "!".
        let mut delta = vec![base_content.len() as u8, base_content.len() as u8 + 1];
        delta.push(0b1001_0001);
        delta.extend_from_slice(&[0, base_content.len() as u8]);
        delta.push(1);
        delta.push(b'!');

        // Hand-build a one-entry thin pack: REF_DELTA against the stored base.
        let mut pack = Vec::new();
        pack.extend_from_slice(b"PACK");
        pack.extend_from_slice(&2u32.to_be_bytes());
        pack.extend_from_slice(&1u32.to_be_bytes());
        push_entry_header(&mut pack, REF_DELTA, delta.len() as u64);
        pack.extend_from_slice(base.as_slice());
        let mut enc = flate2::write::ZlibEncoder::new(Vec::new(), flate2::Compression::default());
        std::io::Write::write_all(&mut enc, &delta).unwrap();
        pack.extend_from_slice(&enc.finish().unwrap());
        let digest: [u8; 20] = Sha1::digest(&pack).into();
        pack.extend_from_slice(&digest);

        let oids = ingest_pack(&pack).unwrap();
        assert_eq!(oids.len(), 1);
        let (t, content) = store::get_object_parsed(&oids[0]).unwrap();
        assert_eq!(t, ObjectType::Blob); // delta inherits the base's type
        assert_eq!(content, b"the quick brown fox jumps over the lazy dog!");
    }

    /// A pack of the given entries: (type code, base oid for a REF_DELTA,
    /// declared size, inflated bytes).
    fn pack_of(entries: &[(u8, Option<Oid>, u64, &[u8])]) -> Vec<u8> {
        let mut pack = Vec::new();
        pack.extend_from_slice(b"PACK");
        pack.extend_from_slice(&2u32.to_be_bytes());
        pack.extend_from_slice(&(entries.len() as u32).to_be_bytes());
        for (code, base, size, bytes) in entries {
            push_entry_header(&mut pack, *code, *size);
            if let Some(base) = base {
                pack.extend_from_slice(base.as_slice());
            }
            let mut enc = flate2::write::ZlibEncoder::new(Vec::new(), flate2::Compression::default());
            std::io::Write::write_all(&mut enc, bytes).unwrap();
            pack.extend_from_slice(&enc.finish().unwrap());
        }
        let digest: [u8; 20] = Sha1::digest(&pack).into();
        pack.extend_from_slice(&digest);
        pack
    }

    fn size_varint(mut n: u64) -> Vec<u8> {
        let mut out = Vec::new();
        loop {
            let byte = (n & 0x7F) as u8;
            n >>= 7;
            if n == 0 {
                out.push(byte);
                return out;
            }
            out.push(byte | 0x80);
        }
    }

    /// Bytes that do not deflate: what a delta's copies cost to store.
    fn noise(n: usize, seed: u8) -> Vec<u8> {
        let mut block: [u8; 20] = Sha1::digest([seed]).into();
        let mut out = Vec::with_capacity(n + 20);
        while out.len() < n {
            out.extend_from_slice(&block);
            block = Sha1::digest(block).into();
        }
        out.truncate(n);
        out
    }

    /// The charge is for what a pack stores: a delta of a few bytes makes
    /// an object of any size out of a base, and the wire size says nothing
    /// of it.
    #[test]
    fn a_pack_is_measured_by_what_it_stores() {
        let base_content = noise(60_000, 1);
        let base = store::put_object(ObjectType::Blob, &base_content);
        // Copy the base (offset 0, size 60000 = 0xEA60) eight times over.
        let mut delta = size_varint(60_000);
        delta.extend(size_varint(480_000));
        for _ in 0..8 {
            delta.extend_from_slice(&[0b1011_0000, 0x60, 0xEA]);
        }
        let pack = pack_of(&[(REF_DELTA, Some(base), delta.len() as u64, &delta)]);
        assert!(pack.len() < 100, "{} bytes on the wire", pack.len());

        let prepared = prepare(&pack).unwrap();
        assert!(prepared.stored_bytes() > 400_000, "{} bytes to store", prepared.stored_bytes());
        let made = prepared.objects[0].0;
        assert!(!store::has_object(&made), "nothing is stored until it is asked for");
        assert_eq!(prepared.store(), vec![made]);
        assert_eq!(store::get_object_parsed(&made).unwrap().1.len(), 480_000);
        // What the store has adds nothing.
        assert_eq!(prepare(&pack).unwrap().stored_bytes(), 0);
    }

    /// Two pushes read before either is stored: the object keeps the
    /// stream that was stored first.
    #[test]
    fn an_object_stored_meanwhile_keeps_its_first_stream() {
        let content = b"overlap overlap overlap overlap overlap overlap".repeat(20);
        let oid = store::oid_of(ObjectType::Blob, &content);
        // The same object as a whole entry at another compression level,
        // so its stream differs from the one the store would deflate.
        let mut pack = Vec::new();
        pack.extend_from_slice(b"PACK");
        pack.extend_from_slice(&2u32.to_be_bytes());
        pack.extend_from_slice(&1u32.to_be_bytes());
        push_entry_header(&mut pack, ObjectType::Blob as u8, content.len() as u64);
        let mut enc = flate2::write::ZlibEncoder::new(Vec::new(), flate2::Compression::none());
        std::io::Write::write_all(&mut enc, &content).unwrap();
        pack.extend_from_slice(&enc.finish().unwrap());
        let digest: [u8; 20] = Sha1::digest(&pack).into();
        pack.extend_from_slice(&digest);

        let late = prepare(&pack).unwrap();
        assert!(late.stored_bytes() > 0);
        store::put_object(ObjectType::Blob, &content);
        let first = store::get_object_stored(&oid).unwrap().zlib().to_vec();
        assert_eq!(late.store(), vec![oid]);
        assert_eq!(store::get_object_stored(&oid).unwrap().zlib(), first.as_slice());
    }

    #[test]
    fn a_delta_resolves_against_an_entry_not_yet_stored() {
        let whole = noise(3_000, 2);
        let mut delta = size_varint(3_000);
        delta.extend(size_varint(3_001));
        delta.extend_from_slice(&[0b1011_0000, 0xB8, 0x0B, 1, b'!']);
        let base = store::oid_of(ObjectType::Blob, &whole);
        // The same whole object twice: held once, counted once.
        let pack = pack_of(&[
            (ObjectType::Blob as u8, None, 3_000, &whole),
            (ObjectType::Blob as u8, None, 3_000, &whole),
            (REF_DELTA, Some(base), delta.len() as u64, &delta),
        ]);
        let prepared = prepare(&pack).unwrap();
        assert!(!store::has_object(&base));
        assert!((6_000..6_200).contains(&prepared.stored_bytes()), "{}", prepared.stored_bytes());
        let oids = prepared.store();
        assert_eq!((oids[0], oids[1]), (base, base));
        let mut expected = whole.clone();
        expected.push(b'!');
        assert_eq!(store::get_object_parsed(&oids[2]).unwrap().1, expected);
    }

    /// The sizes a pack declares cost a few bytes to send: nothing is
    /// inflated, reserved or built past what is allowed.
    #[test]
    fn a_pack_is_held_to_its_sizes() {
        // More inflated than the entry says: stopped at the size.
        let zeros = vec![0u8; 1 << 20];
        let e = prepare(&pack_of(&[(ObjectType::Blob as u8, None, 10, &zeros)])).err().unwrap();
        assert!(e.contains("entry size mismatch"), "{e}");
        // An entry over the cap is refused by its header.
        let e = prepare(&pack_of(&[(ObjectType::Blob as u8, None, MAX_OBJECT + 1, b"x")])).err().unwrap();
        assert!(e.contains("the most is"), "{e}");
        // A delta that says it makes more than the cap: refused before
        // anything is reserved for it.
        let base = store::put_object(ObjectType::Blob, b"base");
        let mut delta = size_varint(4);
        delta.extend(size_varint(u64::MAX >> 1));
        let e = prepare(&pack_of(&[(REF_DELTA, Some(base), delta.len() as u64, &delta)])).err().unwrap();
        assert!(e.contains("delta makes an object"), "{e}");
        // One that copies past the size it gave: refused as it gets there.
        let mut delta = size_varint(4);
        delta.extend(size_varint(6));
        delta.extend_from_slice(&[0b1001_0000, 4, 0b1001_0000, 4]);
        assert!(apply_delta(b"base", &delta).unwrap_err().contains("target size mismatch"));
        // More objects than the pack has bytes for.
        let mut pack = pack_of(&[(ObjectType::Blob as u8, None, 1, b"x")]);
        pack.truncate(pack.len() - 20);
        pack[8..12].copy_from_slice(&u32::MAX.to_be_bytes());
        let digest: [u8; 20] = Sha1::digest(&pack).into();
        pack.extend_from_slice(&digest);
        assert!(prepare(&pack).err().unwrap().contains("object count"));
    }

    /// Small objects, each within the cap, that come to more than a pack
    /// may: refused where the total passes it.
    #[test]
    fn a_pack_is_held_to_a_total() {
        let base_content = vec![7u8; 1 << 20];
        let base = store::put_object(ObjectType::Blob, &base_content);
        // Each delta copies the megabyte 60 times and ends in its own byte.
        // Four are 244 MiB of objects and bases, and the fifth's base passes
        // the total.
        let deltas: Vec<Vec<u8>> = (0..5u8)
            .map(|i| {
                let mut d = size_varint(1 << 20);
                d.extend(size_varint(60 * (1 << 20) + 1));
                for _ in 0..60 {
                    for chunk in 0..16u8 {
                        d.extend_from_slice(&[0b1000_0100, chunk]); // offset chunk << 16, size 0x10000
                    }
                }
                d.extend_from_slice(&[1, i]);
                d
            })
            .collect();
        let entries: Vec<(u8, Option<Oid>, u64, &[u8])> = deltas.iter().map(|d| (REF_DELTA, Some(base), d.len() as u64, d.as_slice())).collect();
        let pack = pack_of(&entries);
        assert!(pack.len() < 2_000, "{}", pack.len());
        let e = prepare(&pack).err().unwrap();
        assert!(e.contains("inflated; push it in parts"), "{e}");
    }

    #[test]
    fn closure_walks_commit_tree_blob() {
        let blob = store::put_object(ObjectType::Blob, b"hello");
        let mut tree = Vec::new();
        tree.extend_from_slice(b"100644 hello.txt\0");
        tree.extend_from_slice(blob.as_slice());
        let tree = store::put_object(ObjectType::Tree, &tree);
        let commit = store::put_object(
            ObjectType::Commit,
            format!(
                "tree {}\nauthor a <a@a> 0 +0000\ncommitter a <a@a> 0 +0000\n\nmsg\n",
                store::oid_hex(&tree)
            )
            .as_bytes(),
        );

        let objects = closure(&[commit], &[]).unwrap();
        assert_eq!(objects.len(), 3);

        // Everything the client already has drops out.
        let objects = closure(&[commit], &[commit]).unwrap();
        assert!(objects.is_empty());

        // The history a push's check stops at is commits and tags, no
        // tree or blob, and a tip the store does not hold is not in it.
        let tag = store::put_object(ObjectType::Tag, format!("object {}\ntype commit\ntag v\n", store::oid_hex(&commit)).as_bytes());
        let absent = Oid::try_from([9u8; 20].as_slice()).unwrap();
        assert_eq!(history(&[tag, absent]), BTreeSet::from([tag, commit]));
        // A walk from the commit stops there at once; from nothing known
        // it visits the three, and they are known after.
        let mut known = history(&[tag]);
        connected(&commit, &mut known).unwrap();
        assert_eq!(known.len(), 2);
        let mut known = BTreeSet::new();
        connected(&commit, &mut known).unwrap();
        assert_eq!(known.len(), 3);

        let pack = build_pack(&closure(&[commit], &[]).unwrap());
        assert_eq!(&pack[..4], b"PACK");
        assert_eq!(u32::from_be_bytes(pack[8..12].try_into().unwrap()), 3);
        let digest: [u8; 20] = Sha1::digest(&pack[..pack.len() - 20]).into();
        assert_eq!(&pack[pack.len() - 20..], digest.as_slice());
    }
}
